      const cycle = dfs(node)
      if (cycle) {
        return cycle.map((name) => ({
          name,
          lifetime: Lifetime.TRANSIENT,
        }))
      }
    }

    return remaining.map((name) => ({
      name,
      lifetime: Lifetime.TRANSIENT,
    }))
  }

