    await expect(container.initialize()).resolves.toBeDefined()
  })

  it('scoped containers initialize independently without reinitializing parent singletons', async () => {
    let dbRuns = 0
    let scopedRuns = 0
    const container = createContainer()
    container.register({
      db: asFunction(() => ({}))
        .singleton()
